DECLARE @books table(id int,title nvarchar(80));
INSERT INTO @books VALUES(1,N'Moon Trip'),(2,N'Garden Days');
SELECT title FROM @books ORDER BY id;

DECLARE @books table(title nvarchar(80),pages int);
INSERT INTO @books VALUES(N'Moon Trip',60),(N'Tiny Seed',20);
SELECT TOP (1) title FROM @books ORDER BY pages,title;

DECLARE @books table(title nvarchar(80),pages int,kind nvarchar(20));
INSERT INTO @books VALUES(N'Moon Trip',60,N'story'),(N'Garden Facts',40,N'science');
SELECT title FROM @books WHERE pages>=50 AND kind=N'story';

DECLARE @reading table(team nvarchar(20),books int);
INSERT INTO @reading VALUES(N'Blue',2),(N'Blue',3),(N'Green',4);
SELECT team,SUM(books) AS total FROM @reading GROUP BY team ORDER BY team;

DECLARE @authors table(id int,name nvarchar(40));
DECLARE @books table(title nvarchar(80),author_id int);
INSERT INTO @authors VALUES(1,N'Mia');
INSERT INTO @books VALUES(N'Moon Trip',1);
SELECT b.title,a.name FROM @books AS b JOIN @authors AS a ON a.id=b.author_id;

DECLARE @books table(title nvarchar(80),pages int);
INSERT INTO @books VALUES(N'Moon Trip',60),(N'Tiny Seed',20);
SELECT title,ROW_NUMBER() OVER(ORDER BY pages,title) AS place FROM @books ORDER BY place;

